scripts.script:
local replicated_storage = game:GetService("ReplicatedStorage");

local auto_delete_settings = require(replicated_storage.Modules.MainRoll.AutoDelete);

getgenv().auto_roll = not getgenv().auto_roll;

if (getgenv().auto_roll) then
    repeat
        local status = auto_delete_settings.getStatus();
        replicated_storage.RemoteEvents.RollRequest:FireServer({
            ["autoDeleteEnabled"] = status.enabled;
            ["autoDeleteRarities"] = status.rarities
        })
        task.wait(1.7); -- you cant go lower or anti cheat will kick you
    until (not getgenv().auto_roll);
end
